    readonly INVALID_SESSION_TOKEN: "INVALID_SESSION_TOKEN";
    /** The first OnRamp page loaded and the session token was accepted. */
    readonly INITIALIZATION_SUCCESS: "INITIALIZATION_SUCCESS";
    /** The OnRamp session expired before the customer completed a deposit. */
    readonly SESSION_TIMEOUT: "SESSION_TIMEOUT";
    /** The customer chose not to complete the deposit. */
    readonly CANCELED_BY_CUSTOMER: "CANCELED_BY_CUSTOMER";
    /** No eligible payment options were available for the customer or region. */
    readonly NO_PAYMENT_OPTIONS: "NO_PAYMENT_OPTIONS";
    /** The customer is still under review and cannot complete a deposit yet. */
    readonly CUSTOMER_PENDING_REVIEW: "CUSTOMER_PENDING_REVIEW";
    /** The customer failed KYC or provider review. */
    readonly CUSTOMER_REJECTED: "CUSTOMER_REJECTED";
    /** A payment provider or integration failure prevented deposit completion. */
    readonly PAYMENT_PROVIDER_ERROR: "PAYMENT_PROVIDER_ERROR";
    /** The customer submitted a deposit request. */
    readonly DEPOSIT_SUBMITTED: "DEPOSIT_SUBMITTED";
    /** A previously submitted deposit settled on-chain. */
    readonly DEPOSIT_SETTLED: "DEPOSIT_SETTLED";
